    /*
     * Add to the MaintenanceOrders
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Asset
     */
    public Asset addToMaintenanceOrders( UUID parentId, MaintenanceOrder addTo ) {
	    LOGGER.info("handling AssignMaintenanceOrdersToAssetEvent - " );
	    
	    Asset parentEntity = repository.findById(parentId).get();
	    MaintenanceOrder child = registry.project( MaintenanceOrder.class, addTo.getMaintenanceOrderId());
	    
	    parentEntity.getMaintenanceOrders().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the MaintenanceOrders
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Asset
     */
	public Asset removeFromMaintenanceOrders( UUID parentId, MaintenanceOrder removeFrom ) {
	    LOGGER.info("handling RemoveMaintenanceOrdersFromAssetEvent " );
	
	    Asset parentEntity = repository.findById(parentId).get();
	    MaintenanceOrder child = registry.project( MaintenanceOrder.class, removeFrom.getMaintenanceOrderId());
	    
	    parentEntity.getMaintenanceOrders().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

